import java.util.*;

class Solution {
  public List<List<Integer>> combinationSum3(int k, int n) {
    List<List<Integer>> ans = new ArrayList<>();
    build(1, k, n, new ArrayList<>(), ans);
    return ans;
  }

  private void build(int start, int k, int remaining, List<Integer> cur, List<List<Integer>> ans) {
    if (cur.size() == k) {
      if (remaining == 0) ans.add(new ArrayList<>(cur));
      return;
    }
    for (int d = start; d <= 9 && d <= remaining; d++) {
      cur.add(d);
      build(d + 1, k, remaining - d, cur, ans);
      cur.remove(cur.size() - 1);
    }
  }
}
